using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class ProbeSeven{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var rows=new List<string>();foreach(var b in Object.FindObjectsByType<WoodlandRoute>()){for(float s=b.title.StartsWith("Storm")?0:100;s<(b.title.StartsWith("Storm")?65:b.Length);s+=1){var p=b.At(s,out var f);foreach(float d in new[]{-2f,0,2f}){var q=p+Vector3.Cross(Vector3.up,f).normalized*d;var hits=Physics.RaycastAll(q+Vector3.up*4,Vector3.down,10,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance);rows.Add($"{b.title} {s} side={d} routeY={p.y:F3} "+string.Join(";",hits.Select(h=>$"{h.collider.name} y={h.point.y:F3} n={h.normal:F2}")));}}}foreach(var p in new[]{new Vector3(286,77,122),new Vector3(168,64,73)})foreach(var c in Physics.OverlapBox(p,new(2,2,2)))rows.Add($"OVERLAP {p} {c.name} {c.bounds}");File.WriteAllLines("Docs/SevenCorrections/failure-probes.txt",rows);return "Local collision probes saved";}}
